def write_all_manuscript_files() -> None:
    write_supporting_markdown_files()
    caps = build_main_captions()
    captions_block = '\n\n'.join(cap for _, _, cap in caps)

    presub_md = f'{CORE_BODY.rstrip()}\n\n## **Figure captions**\n\n{captions_block}\n'
    (DOCS_NEW / 'SAT_CottonRGB_Manuscript_PreSubmission_20260901.md').write_text(presub_md, encoding='utf-8')

    tables_body = build_main_tables_md().replace('# **Main Tables**\n\n', '', 1).strip()
    figures_body = '\n\n'.join(f'![{cap}](../figures/main/{stem}.png)' for _, stem, cap in caps)
    integ_md = (
        f'{CORE_BODY.rstrip()}\n\n'
        f'## **Main Tables**\n\n{tables_body}\n\n'
        f'## **Main Figures**\n\n{figures_body}\n'
    )
    (DOCS_NEW / 'SAT_CottonRGB_Manuscript_V22_Integrated.md').write_text(integ_md, encoding='utf-8')


if __name__ == '__main__':
    write_all_manuscript_files()
    print('Successfully generated Q1 PreSubmission and Integrated manuscripts.')
